import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 20 · Christmas recipe: cut-out sugar cookies that keep their shape
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, every year my granddaughter calls me in December, almost crying. Grandma, my Christmas cookies came out of the oven as blobs. The stars have no points, the snowmen look like potatoes, and the trees ran into each other. And every year I tell her the same thing. It isn't your oven, honey. It's three little mistakes, and my mother fixed every one of them seventy years ago.""",
   "Christmas sugar cookies decorated stars", "BLOBS, NOT STARS")
sc("""So tonight I'm giving you my mother's Christmas sugar cookies. The ones that keep every point on the star. Soft in the middle, crisp on the edge, and perfect for icing. I'll give you every ingredient, every step, and the mistakes that make cookies spread, so yours come out like the picture on the tin.""",
   "cut out cookies baking sheet", "EVERY POINT ON THE STAR")

ch("A Christmas Saturday")
sc("""In our house, cookie day was the second Saturday of December. My mother tied a dish towel around my waist as an apron, gave Danny the job of the flour sifter, and put Bing Crosby on the record player. By noon there was flour on the floor, flour in Danny's hair, and four dozen cookies cooling on every flat surface in the kitchen, including the top of the icebox.""",
   "1950s mother children baking cookies kitchen", "FLOUR IN DANNY'S HAIR")
sc("""My mother's cookie cutters were tin, from the five and dime. A star, a bell, a tree, an angel, and a camel that nobody could explain. Every one of them is in my kitchen drawer today, a little rusty, and I still use the camel every single year. My grandchildren call it the Christmas horse.""",
   "vintage tin cookie cutters", "THE CHRISTMAS HORSE")

sc("""And there was always one rule on cookie day. The broken ones belonged to the bakers. Any star that lost an arm, any angel with a cracked wing, went on a plate in the middle of the table, and Danny and I could eat as many as we wanted. I'm not saying Danny ever broke a few on purpose. But that boy was awfully clumsy every second Saturday of December.""",
   "broken cookies plate kitchen table", "THE BROKEN ONES")

ch("What you need")
sc("""Here's what you need, honey. One cup of butter, that's two sticks, softened but still cool. One cup of white sugar. One egg. One teaspoon of vanilla, and half a teaspoon of almond extract if you have it. That almond is the secret taste people can never guess. Then three cups of flour, one teaspoon of baking powder, and half a teaspoon of salt.""",
   "butter sugar flour eggs baking ingredients", "THE ALMOND SECRET")
sc("""Notice something, sweetheart. Three cups of flour to one cup of butter. Most cookie recipes today use less flour, and that's mistake number one. Too little flour and too much butter is exactly what makes a cookie spread into a puddle. This dough is firmer. It's supposed to be.""",
   "measuring cup flour leveling knife", "THREE CUPS")

ch("Step by step")
sc("""Step one. Beat the butter and the sugar together until it's creamy and pale, about two minutes. But not more. My mother beat it with a wooden spoon, so she never overdid it. With an electric mixer, people beat it for five minutes until it's fluffy like frosting, and all that air makes the cookies puff and spread in the oven.""",
   "creaming butter sugar mixing bowl", "NOT FLUFFY")
sc("""Step two. Beat in the egg, the vanilla and the almond. Then in another bowl, stir the flour, baking powder and salt together, and add it to the butter a little at a time, mixing just until there's no dry flour left. The dough will be thick and a little crumbly. Squeeze a piece in your hand. If it holds together, it's right.""",
   "cookie dough bowl wooden spoon", "SQUEEZE IT")
sc("""And measure the flour right, honey. Don't scoop the cup into the flour bag. That packs it down and you get too much. Spoon the flour into the cup and level it off with the back of a knife. My mother did it over a sheet of wax paper so she could pour the extra right back in the bag.""",
   "spooning flour into measuring cup", "SPOON AND LEVEL")
sc("""Step three, the big one. Split the dough in two, flatten each half into a disk about an inch thick, wrap it in wax paper, and put it in the icebox for at least two hours. Overnight is better. Cold butter is what holds the shape. Warm butter melts the second it hits the oven, and there go your star points.""",
   "dough disk wrapped wax paper refrigerator", "THE NIGHT IN THE COLD")
sc("""Step four. Heat the oven to three hundred seventy-five. Roll the cold dough between two sheets of wax paper or parchment, to about a quarter of an inch thick. That way you don't need to add more flour to the counter, which dries the cookies out. Cut your shapes close together, and lift them onto the baking sheet with a thin spatula.""",
   "rolling cookie dough parchment pin", "A QUARTER INCH")
sc("""Step five, and this is my mother's real secret. Put the whole baking sheet of cut cookies in the icebox for ten minutes before it goes in the oven. Cold cookies into a hot oven. That's how you get sharp edges every time. While one sheet chills, you roll and cut the next one.""",
   "cookie sheet chilling refrigerator", "COLD INTO HOT")
sc("""Step six. Bake for eight to ten minutes, just until the edges are barely golden and the middles look set. Not brown. A brown sugar cookie is a hard cookie. Let them sit on the pan for two minutes, then move them to a rack or a clean dish towel to cool all the way before you ice them.""",
   "baked sugar cookies cooling rack", "BARELY GOLDEN")

ch("Three mistakes that make them spread")
sc("""So the three mistakes, sweetheart, one more time. Mistake one, too little flour. Mistake two, beating the butter until it's fluffy. And mistake three, warm dough. If you skip the icebox because you're in a hurry, every cookie spreads. And never put cut cookies on a hot baking sheet that just came out of the oven. Let the pan cool, or use two pans and switch.""",
   "baking sheets kitchen counter", "NEVER A HOT PAN")
sc("""And one more, honey. Don't grease the pan. Butter on the pan makes the cookies slide and spread as the dough melts. Use a plain pan, or parchment paper. My mother had two old aluminum sheets, never greased, and her cookies never stuck in fifty years.""",
   "aluminum baking sheet parchment", "DON'T GREASE IT")

sc("""And if your kitchen is warm, honey, with the oven going all morning, put the rolling pin in the icebox too, and work with only half the dough at a time while the other half stays cold. The minute the dough feels soft and sticky, back in the icebox for fifteen minutes. My mother used to say, when the dough gets tired, let it rest. Same as children.""",
   "rolling pin dough kitchen counter", "WHEN THE DOUGH GETS TIRED")

ch("The icing")
sc("""Now the icing, the part the children love. Two cups of powdered sugar, two tablespoons of milk, a half teaspoon of vanilla, and a tablespoon of light corn syrup. The corn syrup makes it shiny and lets it dry hard enough to stack the cookies. Stir it smooth. If it's too thick, add milk a few drops at a time. It should run off the spoon slowly, like honey.""",
   "white icing bowl spoon", "LIKE HONEY")
sc("""Split it into little bowls and color them with a drop or two of food coloring. Spread it with the back of a spoon, or put it in a sandwich bag, snip off the tiniest corner, and pipe the lines. Sprinkle colored sugar on while the icing is wet. Then let them dry overnight on the counter before you stack them in a tin.""",
   "decorating cookies icing sprinkles children", "DRY OVERNIGHT")
sc("""And here's how my mother made colored sugar when we couldn't afford the jars from the store. Half a cup of white sugar in a jar with three drops of food coloring. Put the lid on and shake it hard for a minute. Spread it on a plate to dry for an hour. Red, green, and yellow for the stars. It cost about two cents.""",
   "colored sugar sprinkles jar", "TWO CENTS")

sc("""If you want to hang cookies on the tree, the way we did, poke a hole near the top of each one with a drinking straw before it goes in the oven. When they're cool and iced, thread a piece of red yarn through and tie a loop. My father always said they were the only ornaments in the house he was allowed to eat, and every year two or three of them disappeared from the back of the tree.""",
   "cookie ornaments hanging Christmas tree", "ORNAMENTS YOU CAN EAT")

ch("Keeping them")
sc("""Iced sugar cookies keep two weeks in a tin with wax paper between the layers. And the dough freezes beautifully, wrapped tight, for three months. I make three batches of dough right after Thanksgiving and freeze them. Then on cookie day, I just thaw one in the icebox overnight and we're rolling by nine in the morning.""",
   "cookie tin wax paper layers", "MAKE THE DOUGH IN NOVEMBER")
sc("""And give them away, sweetheart. A plate of iced stars covered in wax paper and tied with string, for the mailman, the neighbor, the lady at church who lives alone. Nobody ever forgets who brought them cookies at Christmas. My mother's plates went down Elm Street every year, and people still talked about them at her funeral.""",
   "plate of cookies gift neighbor", "NOBODY FORGETS")

ch("Grandma's kitchen")
sc("""So here it is, honey. Three cups of flour to one cup of butter. Cream it, don't whip it. Chill the dough, then chill the cut cookies again. Cold into a hot oven, eight to ten minutes, barely golden. And corn syrup in the icing. That's how you get stars with every point, every time.""",
   "star sugar cookies perfect edges", "EVERY POINT, EVERY TIME")
sc("""Tell me in the comments, sweetheart. What's your favorite cookie cutter? And do you have a strange one, like my mother's camel? Every day I'm bringing you a recipe from my kitchen. Good night, honey. Go make some stars.""",
   "Christmas cookies plate warm kitchen", "WHAT'S YOUR CUTTER?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma20", "The Christmas Sugar Cookies That NEVER Spread (Grandma's 3 Secrets)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Recipe as written by Grandma Ruth: 1 cup butter, 1 cup sugar, 1 egg, 1 tsp vanilla, 1/2 tsp almond extract, 3 cups flour, 1 tsp baking powder, 1/2 tsp salt; chill 2 hours; 1/4 inch thick; chill cut cookies 10 min; 375 F for 8 to 10 minutes.",
      "Icing: 2 cups powdered sugar, 2 tbsp milk, 1/2 tsp vanilla, 1 tbsp light corn syrup."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
